import {test} from 'node:test';import assert from 'node:assert/strict';import {required,status,overall,csv,sessionSeconds,hoursLabel,duration,hms,breakSeconds,weekStart,reportBuckets,zonedClock} from './logic.js';
const e={id:'a',active:true,join_date:'2026-01-01',timezone:'Asia/Dhaka',workdays:[0,1,2,3,4,5,6],country:'Bangladesh'},day='2026-11-03',clock=new Date('2026-11-03T10:00:00Z'),empty={leaves:[],holidays:[],updates:[],sessions:[],exceptions:[]};const w={employee_id:'a',work_date:day,started_at:'2026-11-03T05:00:00Z',break_seconds:3600,paused_at:null,ended_at:null};
test('midpoint due at four net hours, EOD at eight',()=>{assert.equal(sessionSeconds(w,clock),14400);assert.equal(status(e,day,'midday',{...empty,sessions:[w]},clock),'Due');assert.equal(status(e,day,'eod',{...empty,sessions:[w]},clock),'Pending');assert.equal(status(e,day,'eod',{...empty,sessions:[{...w,started_at:'2026-11-03T01:00:00Z'}]},clock),'Due')});
test('ongoing break freezes net time',()=>{const paused={...w,paused_at:'2026-11-03T09:00:00Z'};assert.equal(sessionSeconds(paused,clock),10800);assert.equal(sessionSeconds(paused,new Date('2026-11-03T11:00:00Z')),10800)});
test('ended session stops accruing time',()=>{assert.equal(sessionSeconds({...w,ended_at:'2026-11-03T09:00:00Z'},new Date('2026-11-04T11:00:00Z')),10800)});
test('reason pending differs from accepted and rejected',()=>{for(const [review,expected] of [['pending','Reason submitted'],['accepted','Excused'],['declined','Due']])assert.equal(status(e,day,'midday',{...empty,sessions:[w],exceptions:[{employee_id:'a',work_date:day,status:review}]},clock),expected);assert.equal(overall('Reason submitted','Submitted'),'Review needed');assert.equal(overall('Excused','Submitted'),'Complete · Exception')});
test('submitted midpoint overrides old exception',()=>{assert.equal(status(e,day,'midday',{...empty,updates:[{employee_id:'a',work_date:day,kind:'midday'}],exceptions:[{employee_id:'a',work_date:day,status:'accepted'}]},clock),'Submitted')});
test('no sign-in is separate from due/missing',()=>{assert.equal(status(e,day,'midday',empty,clock),'Not signed in');assert.equal(status(e,day,'midday',{...empty,sessions:[{...w,ended_at:clock.toISOString()}]},clock),'Missing')});
test('overnight session remains attached to its work date',()=>{const x={...w,started_at:'2026-11-03T16:00:00Z',break_seconds:0};assert.equal(status(e,day,'midday',{...empty,sessions:[x]},new Date('2026-11-03T21:00:00Z')),'Due')});
test('stale session is not treated as verified hours',()=>{assert.equal(hoursLabel({...w,started_at:'2026-11-02T01:00:00Z'},clock),'Needs review')});
test('approved full/half leave and employment boundaries',()=>{const leave={employee_id:'a',status:'approved',start_date:day,end_date:day,portion:'full'};assert.equal(required(e,day,'eod',[leave]),false);assert.equal(required(e,day,'eod',[{...leave,portion:'half'}]),true);assert.equal(required(e,day,'midday',[{...leave,portion:'half'}]),false);assert.equal(required(e,'2025-12-31','eod'),false);assert.equal(required({...e,active:false,end_date:day},day,'eod'),true)});
test('CSV formula protection and hours formatting',()=>{assert.ok(csv([['=1+1','a"b']]).includes("'="));assert.ok(csv([['a"b']]).includes('a""b'));assert.equal(duration(28800),'8h 00m')});

test('seconds, breaks and Monday-based reporting buckets',()=>{assert.equal(hms(36001),'10:00:01');assert.equal(weekStart('2026-11-01'),'2026-10-26');assert.equal(breakSeconds({...w,paused_at:'2026-11-03T09:30:00Z'},clock),5400);const rows=reportBuckets([e],{...empty,sessions:[w]},day,day,clock);assert.equal(rows[0].week,'2026-11-02');assert.equal(rows[0].seconds,14400);assert.equal(rows[0].breaks,3600);assert.equal(rows[0].midRequired+rows[0].eodRequired,2)});
test('EOD preparation opens 45 minutes before an 8-hour finish',()=>{const x={...w,started_at:'2026-11-03T01:45:00Z'};assert.equal(sessionSeconds(x,clock),26100);assert.equal(status(e,day,'eod',{...empty,sessions:[x]},clock),'Due')});

test('12-hour world clocks use local dates and Eastern daylight saving transitions',()=>{assert.equal(zonedClock('2026-07-01T16:00:00Z','America/New_York').abbreviation,'EDT');assert.equal(zonedClock('2026-12-01T17:00:00Z','America/New_York').abbreviation,'EST');assert.equal(zonedClock('2026-03-08T06:59:59Z','America/New_York').time,'01:59:59 AM');assert.equal(zonedClock('2026-03-08T07:00:00Z','America/New_York').time,'03:00:00 AM');assert.equal(zonedClock('2026-11-01T06:00:00Z','America/New_York').time,'01:00:00 AM');assert.equal(zonedClock('2026-11-03T18:30:00Z','Asia/Dhaka').date,'04 Nov 2026');assert.equal(zonedClock('2026-11-03T18:30:00Z','Asia/Karachi').time,'11:30:00 PM')});
